import { describe, it, expect } from "vitest";
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { UnknownLayoutError } from "../src/abi/layout.js";
import { pythPriceToLotE6V22, tokenPriceToLotE6V22, lotExpOfMarketV22, lotExpOfProfileV22 } from "../src/abi/v22-lot.js";

// Differential vs percolator-prog origin/feat/v22-rc23-2026-10-22 src/v16_program.rs (read_pyth_price_e12 :12579,
// leg_e12_in_range :12550, compose_price_e12_to_e6 :12882). Fixture generated by scripts/v22-lot-price-oracle.rs,
// which copies that Rust logic verbatim (single leg). 25,328 rows: 20,000 seeded random + edge grid.
const MAX_ORACLE_PRICE = 1_000_000_000_000n;
const rows = readFileSync(fileURLToPath(new URL("./fixtures/v22-lot-price-prog.txt", import.meta.url)), "utf8")
  .trim().split("\n").map((l) => {
    const [p, e, lot, res] = l.split(" ");
    return { price: BigInt(p), expo: Number(e), lot: Number(lot), res };
  });

describe("pythPriceToLotE6V22 vs prog rc23 single-leg path", () => {
  it("fixture size", () => expect(rows.length).toBeGreaterThanOrEqual(20_000));

  it("every price the program accepts converts to exactly the same e6 value (0 mismatches)", () => {
    let ok = 0;
    const mismatches: string[] = [];
    for (const r of rows) {
      if (!r.res.startsWith("ok:")) continue;
      ok++;
      const got = pythPriceToLotE6V22(r.price, r.expo, r.lot);
      if (got !== BigInt(r.res.slice(3))) mismatches.push(`${r.price} ${r.expo} ${r.lot}: sdk ${got} prog ${r.res}`);
    }
    expect(ok).toBeGreaterThan(5_000);
    expect(mismatches).toEqual([]);
  });

  it("where the program refuses, the SDK returns 0, > MAX_ORACLE_PRICE, or the input is outside the prog's expo range", () => {
    const bad: string[] = [];
    for (const r of rows) {
      if (r.res.startsWith("ok:")) continue;
      const got = pythPriceToLotE6V22(r.price, r.expo, r.lot);
      const documented = got === 0n || got > MAX_ORACLE_PRICE;
      if (!documented) bad.push(`${r.price} ${r.expo} ${r.lot}: sdk ${got} prog ${r.res}`);
    }
    expect(bad).toEqual([]);
  });

  it("prog refuses a leg whose E12 read is 0 (price below 1e-12 per token) even when lot_exp would lift it; SDK returns 0 or a lifted value, never throws", () => {
    // 1 * 10^-14 -> E12 read 0 (prog: OracleInvalid). SDK result is 0 here too because e12 is 0.
    expect(pythPriceToLotE6V22(1n, -14, 15)).toBe(0n);
    expect(rows.find((r) => r.price === 1n && r.expo === -14 && r.lot === 15)!.res).toBe("err:OracleInvalid");
  });

  it("edges: price 1, i64::MAX, u64::MAX (not representable on-chain; Pyth price is i64), sub-1e-6 prices", () => {
    expect(pythPriceToLotE6V22(1n, -12, 6)).toBe(1n);
    expect(pythPriceToLotE6V22(1n, -6, 0)).toBe(1n);
    expect(pythPriceToLotE6V22(1n, -8, 0)).toBe(0n); // below 1e-6: unreadable at lot 0
    expect(pythPriceToLotE6V22(1n, -8, 2)).toBe(1n);
    const i64max = 9_223_372_036_854_775_807n;
    expect(pythPriceToLotE6V22(i64max, -12, 0)).toBe(i64max / 1_000_000n);
    expect(() => pythPriceToLotE6V22(18_446_744_073_709_551_615n, -12, 0)).not.toThrow();
  });
});

describe("expo outside the prog's +-18 window (read_pyth_price_e12 :12606)", () => {
  it("returns 0 (= the program would refuse), not a usable price", () => {
    expect(pythPriceToLotE6V22(10n ** 17n, -19, 6)).toBe(0n);
    expect(pythPriceToLotE6V22(1n, 19, 0)).toBe(0n);
    expect(pythPriceToLotE6V22(1n, 18, 0)).toBeGreaterThan(0n);
  });
});

describe("lead 2 and 3: guards", () => {
  it("lotExp guard: assertLotExp throws plain Error, byte readers throw RangeError (documented split)", () => {
    expect(() => pythPriceToLotE6V22(1n, -6, 16)).toThrow(Error);
    expect(() => pythPriceToLotE6V22(1n, -6, 16)).not.toThrow(RangeError);
    expect(() => tokenPriceToLotE6V22(1n, 16)).toThrow(Error);
    expect(() => tokenPriceToLotE6V22(1n, 16)).not.toThrow(RangeError);
    const d = new Uint8Array(32);
    d[19] = 16;
    expect(() => lotExpOfProfileV22(d, 0)).toThrow(RangeError);
    expect(() => lotExpOfProfileV22(d, 0)).toThrow("lot_exp byte 16 is above 15");
  });
  it("lotExpOfMarketV22 on garbage is UnknownLayoutError, not RangeError", () => {
    expect(() => lotExpOfMarketV22(new Uint8Array(8))).toThrow(UnknownLayoutError);
    expect(() => lotExpOfMarketV22(new Uint8Array(8))).not.toThrow(RangeError);
  });
  it("price <= 0 throws, matching the prog (read_pyth_price_e12 :12606 rejects msg.price <= 0)", () => {
    expect(() => pythPriceToLotE6V22(0n, -6, 0)).toThrow("price must be > 0");
    expect(() => pythPriceToLotE6V22(-1n, -6, 0)).toThrow("price must be > 0");
  });
});
